using Azure.Search.Documents;using Azure.Search.Documents.Models;using Azure.Messaging.ServiceBus;using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;using System.Text.Json;
public sealed class ServiceBusClientFactory(IConfiguration c){readonly ServiceBusClient client=!string.IsNullOrWhiteSpace(c["ServiceBus:ConnectionString"])?new(c["ServiceBus:ConnectionString"]!):new(c["ServiceBus:FullyQualifiedNamespace"]!,new Azure.Identity.DefaultAzureCredential());public ServiceBusProcessor Create(string t,string s)=>client.CreateProcessor(t,s,new ServiceBusProcessorOptions{MaxConcurrentCalls=8,PrefetchCount=50,AutoCompleteMessages=false});}
public sealed class Worker(ServiceBusClientFactory factory,SearchClient index,IndexingBatchBuilder builder,IMessagePublisher publisher,ILogger<Worker> log):BackgroundService{protected override async Task ExecuteAsync(CancellationToken ct){var p=factory.Create(Topics.EmbeddingEvents,"indexing-sub");p.ProcessMessageAsync+=Handle;p.ProcessErrorAsync+=Error;await p.StartProcessingAsync(ct);try{await Task.Delay(Timeout.Infinite,ct);}catch(OperationCanceledException){}finally{await p.StopProcessingAsync();await p.DisposeAsync();}}async Task Handle(ProcessMessageEventArgs a){try{var m=JsonSerializer.Deserialize<EmbeddingsCreated>(a.Message.Body.ToString(),new JsonSerializerOptions(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Invalid embeddings event");var docs=builder.Build(m,m.AllowedPrincipalIds);var batch=new IndexDocumentsBatch<SearchDocument>();foreach(var d in docs)batch.Actions.Add(IndexDocumentsAction.Upload(d));await index.IndexDocumentsAsync(batch,cancellationToken:a.CancellationToken);await publisher.PublishAsync(Topics.IndexingEvents,new IndexingCompleted(Guid.NewGuid(),m.TenantId,m.DocumentId,m.VersionId,docs.Count,DateTimeOffset.UtcNow,m.CorrelationId),m.CorrelationId,a.CancellationToken);await a.CompleteMessageAsync(a.Message);}catch(Exception ex){log.LogError(ex,"Indexing failed");if(a.Message.DeliveryCount>=5)await a.DeadLetterMessageAsync(a.Message,"max-delivery",ex.Message);else await a.AbandonMessageAsync(a.Message);}}Task Error(ProcessErrorEventArgs e){log.LogError(e.Exception,"Indexing Service Bus error");return Task.CompletedTask;}}